escenas.Mundo:
// Mundo compartido: «Una palabra cambió lo que recordaron del choque».
// Maqueta en corte de una salita de cine oscura: pantalla al fondo, dos filas de butacas, Mía (roja) en el centro.
// paso 0: sala vacía; sobre Mía, su cabeza en corte con un cajón de recuerdo dorado medio abierto.
// paso 1: pantalla vacía, Mía en su butaca, la palabra «estrellaron» flota sobre ella.
// paso 2: la pantalla muestra los dos autitos ya chocados.
// paso 3: + dos investigadores a la izquierda de la pantalla y el rótulo «1974» arriba.
// paso 4: + estudiantes en las butacas; la investigadora alza la tarjeta del velocímetro.
// paso 5: la sala se divide en dos mitades, cada una con su burbuja de pregunta.
// paso 6: + tarjeta de barras de velocidad (41 vs 32 mph).
// paso 7: mitades juntas, sello «IGUAL» en la pantalla, palabra otra vez sobre Mía.
// paso 8: sala más oscura, calendario «+7 días», la investigadora se acerca con la tarjeta de vidrios rotos.
// paso 9: la tarjeta de vidrios aparece tachada.
// paso 10: tarjeta de barras «sí vi vidrios» sobre la pantalla; cabeza de Mía con rompecabezas incompleto.
// paso 11: rompecabezas completo con la pieza-palabra dorada.
import React from 'react';
import {Pieza, Cartel, Linea, Brillo, flotar} from '../lib3d';
import type {Paleta, V3} from '../lib3d';
import {Persona2D, Cabeza2D, Nube, Efecto, Sombra, Cajon, oscurecer} from '../lib25d';

export const PARTES = [
  'sala', 'pantalla', 'autos', 'butacas', 'mia', 'palabra', 'cabeza', 'cajon', 'investigadores', 'rotulo',
  'estudiantes', 'tarjeta', 'burbujas', 'barras', 'sello', 'calendario', 'vidrios', 'tachado', 'barrasvidrios',
  'rompecabezas', 'pieza',
] as const;

export type ParteProps = {paleta: Paleta; resaltado?: boolean; frame?: number};
export type MundoProps = {paso: number; frame: number; fps: number; paleta: Paleta; ocultar?: string[]; resaltar?: string[]};

const col = (p: Paleta) => ({
  prota: p.acentos[0], sec: p.acentos[1], oro: p.acentos[2], extra: p.acentos[3], suelo: p.acentos[4] ?? '#2A1618',
  marfil: p.tinta, carbon: '#141012',
});

// ---------- estados por paso (la escena anima entre uno y otro) ----------
/** Separación de las dos mitades de la sala (m a cada lado). */
export const division = (paso: number) => (paso === 5 || paso === 6 ? 0.16 : 0);
/** Luz de los apliques de la sala (1 normal, menos = más oscuro). */
export const penumbra = (paso: number) => (paso === 8 || paso === 9 ? 0.45 : 1);
/** Avance de los autos en la pantalla: 0 = separados en los bordes, 1 = chocados en el centro. */
export const avanceAutos = (paso: number) => (paso >= 2 ? 1 : 0);
/** Dónde está la investigadora de la carpeta (se acerca al público en el paso 8). */
export const posInvestigadora = (paso: number): V3 => (paso >= 8 ? [-0.62, 0, -0.18] : [-0.86, 0, -0.55]);
/** Altura de las barras (0..1) en las tarjetas de datos. */
export const crecerBarras = (paso: number, desde: number) => (paso >= desde ? 1 : 0);

// Geometría de la sala
const PANT_Y = 1.06;
const PANT_Z = -0.86;
const FILAS = [{z: 0.12, y: 0}, {z: 0.6, y: 0.12}];
const COLS = [-0.62, -0.31, 0, 0.31, 0.62];
const asiento = (fila: number, c: number, sep: number): V3 => {
  const x = COLS[c];
  return [x + (x < 0 ? -sep : x > 0 ? sep : 0), FILAS[fila].y, FILAS[fila].z];
};
export const POS_MIA: V3 = [0, 0, 0.12];
export const POS_CABEZA: V3 = [0, 0.84, 0.24];
export const POS_PALABRA: V3 = [0, 0.86, 0.3];

// ---------- partes ----------
export const Sala: React.FC<ParteProps & {luz?: number}> = ({paleta, luz = 1}) => {
  const c = col(paleta);
  const pared = oscurecer(c.prota, 0.32);
  return (
    <group>
      <Pieza forma="caja" medidas={[2.3, 0.08, 2.0]} color={c.suelo} posicion={[0, -0.04, 0]} />
      <Pieza forma="caja" medidas={[2.3, 0.06, 0.06]} color={c.oro} posicion={[0, -0.01, 1.0]} />
      <Pieza forma="caja" medidas={[2.3, 1.9, 0.06]} color={pared} posicion={[0, 0.95, -0.97]} />
      <Pieza forma="caja" medidas={[0.06, 1.9, 1.4]} color={oscurecer(pared, 0.85)} posicion={[-1.15, 0.95, -0.3]} />
      <Pieza forma="caja" medidas={[0.06, 1.9, 1.4]} color={oscurecer(pared, 0.85)} posicion={[1.15, 0.95, -0.3]} />
      {/* escenario y tarima de la fila de atrás */}
      <Pieza forma="caja" medidas={[1.9, 0.14, 0.3]} color={oscurecer(c.suelo, 0.8)} posicion={[0, 0.07, -0.78]} />
      <Pieza forma="caja" medidas={[2.2, 0.12, 0.55]} color={oscurecer(c.suelo, 1.15)} posicion={[0, 0.06, 0.62]} />
      {/* cortinas a los lados de la pantalla */}
      {[-1, 1].map((l) =>
        [0, 1, 2].map((i) => (
          <Pieza key={`${l}${i}`} forma="cilindro" medidas={[0.055, 0.07, 1.62, 12]} color={i === 1 ? oscurecer(c.prota, 0.8) : c.prota}
            posicion={[l * (0.84 + i * 0.09), 0.95, -0.9 + i * 0.012]} />
        )),
      )}
      <Pieza forma="caja" medidas={[2.0, 0.14, 0.12]} color={c.prota} posicion={[0, 1.83, -0.9]} />
      {/* apliques dorados: la única luz de la sala */}
      {[-1, 1].map((l) => (
        <group key={l} position={[l * 1.1, 1.2, -0.35]}>
          <Pieza forma="cono" medidas={[0.07, 0.12]} color={c.oro} rotacion={[0, 0, Math.PI]} brillo={c.oro} />
          <Brillo posicion={[0, -0.09, 0]} color={c.oro} radio={0.03} luz={0.9 * luz} />
        </group>
      ))}
    </group>
  );
};

export const Pantalla: React.FC<ParteProps> = ({paleta, resaltado}) => {
  const c = col(paleta);
  return (
    <group position={[0, PANT_Y, PANT_Z]}>
      <Pieza forma="caja" medidas={[1.52, 0.9, 0.05]} color={resaltado ? c.oro : c.carbon} posicion={[0, 0, -0.03]} />
      <Pieza forma="caja" medidas={[1.4, 0.78, 0.01]} color="#4A3A38" brillo="#3B2C28" contorno={false} />
      {/* suelo de la carretera dibujada en la pantalla */}
      <Pieza forma="caja" medidas={[1.3, 0.03, 0.006]} color={c.marfil} posicion={[0, -0.24, 0.01]} contorno={false} opacidad={0.5} />
    </group>
  );
};

const Autito: React.FC<{color: string; x: number; espejo?: boolean; inclina?: number}> = ({color, x, espejo, inclina = 0}) => (
  <group position={[x, -0.16, 0.03]} rotation={[0, 0, inclina]} scale={[espejo ? -1 : 1, 1, 1]}>
    <Pieza forma="caja" medidas={[0.24, 0.07, 0.03]} color={color} />
    <Pieza forma="caja" medidas={[0.12, 0.06, 0.028]} color={color} posicion={[-0.02, 0.06, 0]} />
    <Pieza forma="caja" medidas={[0.05, 0.035, 0.03]} color="#CFE3E6" posicion={[0.015, 0.06, 0.002]} contorno={false} />
    {[-0.07, 0.07].map((r) => (
      <Pieza key={r} forma="cilindro" medidas={[0.032, 0.032, 0.035, 16]} color="#141012" posicion={[r, -0.04, 0.004]} rotacion={[Math.PI / 2, 0, 0]} />
    ))}
  </group>
);

/** Autos rojo y azul en la pantalla. avance 0..1 los lleva de los bordes al choque. */
export const Autos: React.FC<ParteProps & {avance?: number}> = ({paleta, resaltado, avance = 1}) => {
  const c = col(paleta);
  const x = 0.52 - 0.39 * avance;
  const golpe = avance >= 1 ? 0.06 : 0;
  return (
    <group position={[0, PANT_Y, PANT_Z]}>
      <Autito color={resaltado ? c.oro : '#B8343C'} x={-x} inclina={golpe} />
      <Autito color={resaltado ? c.oro : '#3E7A86'} x={x} espejo inclina={-golpe} />
    </group>
  );
};

export const Butacas: React.FC<ParteProps & {sep?: number}> = ({paleta, resaltado, sep = 0}) => {
  const c = col(paleta);
  const tela = resaltado ? c.oro : oscurecer(c.prota, 0.7);
  return (
    <group>
      {FILAS.map((_, f) =>
        COLS.map((__, i) => {
          const p = asiento(f, i, sep);
          return (
            <group key={`${f}-${i}`} position={p}>
              <Pieza forma="caja" medidas={[0.25, 0.14, 0.22]} color={tela} posicion={[0, 0.07, 0]} />
              <Pieza forma="caja" medidas={[0.25, 0.3, 0.05]} color={tela} posicion={[0, 0.2, 0.12]} rotacion={[0.08, 0, 0]} />
            </group>
          );
        }),
      )}
    </group>
  );
};

export const Mia: React.FC<ParteProps & {pose?: string; fps?: number}> = ({paleta, resaltado, frame = 0, fps = 30, pose = 'parado'}) => {
  const c = col(paleta);
  return (
    <group>
      <Persona2D pose={pose} color={resaltado ? c.oro : c.prota} alto={0.5} posicion={[POS_MIA[0], 0.06, POS_MIA[2] + 0.02]} frame={frame} fps={fps} />
      <Sombra posicion={[0, 0, 0.12]} radio={0.16} />
    </group>
  );
};

export const Palabra: React.FC<ParteProps & {fps?: number}> = ({paleta, frame = 0, fps = 30}) => {
  const c = col(paleta);
  const y = POS_PALABRA[1] + flotar(frame, 0.025, 70);
  return (
    <group position={[POS_PALABRA[0], y, POS_PALABRA[2]]}>
      <Efecto tipo="destello" tam={0.5} color={c.oro} posicion={[0, 0, -0.02]} frame={frame} fps={fps} opacidad={0.6} />
      <Cartel texto="estrellaron" posicion={[0, 0, 0]} alto={0.13} fondo="transparent" colorTexto={c.oro} borde="#1B1B1F" />
    </group>
  );
};

export const Cabeza: React.FC<ParteProps & {fps?: number}> = ({paleta, resaltado, frame = 0, fps = 30}) => {
  const c = col(paleta);
  return (
    <Cabeza2D alto={0.62} fuerza={resaltado ? 1 : 0.35} color={oscurecer(c.extra, 1.1)} posicion={POS_CABEZA} opacidad={0.92} frame={frame} fps={fps} />
  );
};

/** Cajón de recuerdo dentro de la cabeza. abierto 0..1. */
export const CajonRecuerdo: React.FC<ParteProps & {abierto?: number}> = ({paleta, resaltado, abierto = 0.45}) => {
  const c = col(paleta);
  return (
    <group position={[POS_CABEZA[0] + 0.01, POS_CABEZA[1] + 0.08, POS_CABEZA[2] + 0.05]}>
      <Cajon abierto={abierto} color={resaltado ? c.oro : c.sec} ancho={0.17} alto={0.1} fondo={0.12} rotacion={[0.25, 0.5, 0]} />
      <Brillo posicion={[0, 0.02, 0.05]} color={c.oro} radio={0.022} />
    </group>
  );
};

export const Investigadores: React.FC<ParteProps & {paso?: number; fps?: number}> = ({paleta, resaltado, frame = 0, fps = 30, paso = 3}) => {
  const c = col(paleta);
  const a = posInvestigadora(paso);
  const bata = resaltado ? c.oro : c.marfil;
  return (
    <group>
      <Persona2D pose={paso === 4 || paso >= 8 ? 'senala' : 'parado'} color={bata} alto={0.8} posicion={[a[0], 0.14, a[2]]} frame={frame} fps={fps} />
      {/* carpeta */}
      <Pieza forma="caja" medidas={[0.09, 0.12, 0.015]} color={c.sec} posicion={[a[0] - 0.12, 0.6, a[2] + 0.04]} rotacion={[0, 0, 0.2]} />
      <Persona2D pose="parado" color={bata} alto={0.84} posicion={[-1.02, 0.14, -0.4]} frame={frame} fps={fps} />
      {/* cronómetro */}
      <group position={[-0.9, 0.62, -0.36]}>
        <Pieza forma="cilindro" medidas={[0.035, 0.035, 0.015, 20]} color={c.oro} rotacion={[Math.PI / 2, 0, 0]} />
        <Pieza forma="caja" medidas={[0.012, 0.02, 0.012]} color={c.oro} posicion={[0, 0.045, 0]} />
      </group>
      <Sombra posicion={[a[0], 0.14, a[2]]} radio={0.2} />
      <Sombra posicion={[-1.02, 0.14, -0.4]} radio={0.2} />
    </group>
  );
};

export const Rotulo: React.FC<ParteProps> = ({paleta, resaltado}) => {
  const c = col(paleta);
  return (
    <group position={[0, 1.66, -0.84]}>
      <Pieza forma="caja" medidas={[0.46, 0.17, 0.03]} color={c.carbon} />
      <Cartel texto="1974" posicion={[0, 0, 0.02]} alto={0.15} fondo="transparent" colorTexto={resaltado ? c.marfil : c.oro} borde="#1B1B1F" rotacion={[0, 0, 0.0001]} />
    </group>
  );
};

const Estudiante: React.FC<{color: string; p: V3; frame: number; fps: number}> = ({color, p, frame, fps}) => (
  <Persona2D pose="parado" color={color} alto={0.44} posicion={[p[0], p[1] + 0.06, p[2] + 0.02]} frame={frame} fps={fps} />
);

export const Estudiantes: React.FC<ParteProps & {sep?: number; fps?: number}> = ({paleta, resaltado, frame = 0, fps = 30, sep = 0}) => {
  const c = col(paleta);
  const tonos = [c.sec, c.extra, oscurecer(c.sec, 1.35), oscurecer(c.extra, 0.8)];
  const items: React.ReactNode[] = [];
  FILAS.forEach((_, f) =>
    COLS.forEach((__, i) => {
      if (f === 0 && i === 2) return; // butaca de Mía
      items.push(<Estudiante key={`${f}-${i}`} color={resaltado ? c.oro : tonos[(f * 2 + i) % 4]} p={asiento(f, i, sep)} frame={frame} fps={fps} />);
    }),
  );
  return <group>{items}</group>;
};

/** Tarjeta con signo de pregunta y velocímetro, en alto en la mano de la investigadora. */
export const Tarjeta: React.FC<ParteProps> = ({paleta, resaltado}) => {
  const c = col(paleta);
  return (
    <group position={[-0.72, 1.02, -0.5]} rotation={[0, 0, -0.08]}>
      <Pieza forma="caja" medidas={[0.34, 0.24, 0.012]} color={resaltado ? c.oro : c.marfil} />
      <Pieza forma="toro" medidas={[0.07, 0.01, Math.PI]} color={c.sec} posicion={[0.05, -0.05, 0.01]} />
      <Linea desde={[0.05, -0.05, 0.012]} hasta={[0.1, 0.0, 0.012]} grosor={0.007} color={c.prota} />
      <Cartel texto="?" posicion={[-0.1, 0.0, 0.012]} alto={0.16} fondo="transparent" colorTexto={c.prota} rotacion={[0, 0, 0.0001]} />
    </group>
  );
};

/** Burbujas de pregunta sobre cada mitad: izquierda «estrellaron» (fuerte), derecha «tocaron» (suave). */
export const Burbujas: React.FC<ParteProps & {fps?: number}> = ({paleta, resaltado, frame = 0, fps = 30}) => {
  const c = col(paleta);
  const f = flotar(frame, 0.02, 80);
  return (
    <group>
      <group position={[-0.58, 1.02 + f, 0.42]}>
        <Nube ancho={0.62} color={c.marfil} frame={frame} fps={fps} />
        <Cartel texto={'¿se\nESTRELLARON?'} posicion={[0, 0.0, 0.02]} alto={0.12} fondo="transparent" colorTexto={c.prota} />
        <Efecto tipo="chispa" tam={0.25} color={c.oro} posicion={[0.28, 0.18, 0.03]} frame={frame} fps={fps} />
      </group>
      <group position={[0.58, 1.0 - f, 0.42]}>
        <Nube ancho={0.58} color={resaltado ? c.oro : oscurecer(c.marfil, 0.85)} frame={frame} fps={fps} />
        <Cartel texto={'¿se\ntocaron?'} posicion={[0, 0.0, 0.02]} alto={0.1} fondo="transparent" colorTexto={c.sec} />
      </group>
    </group>
  );
};

/** Tablero con barras sobre un caballete a la derecha: altura 0..1. */
export const Barras: React.FC<ParteProps & {altura?: number}> = ({paleta, resaltado, altura = 1}) => {
  const c = col(paleta);
  const b = (h: number) => Math.max(0.001, h * altura);
  return (
    <group position={[0.86, 0.14, -0.45]}>
      <Linea desde={[-0.14, 0, 0.05]} hasta={[-0.08, 0.6, 0]} grosor={0.012} color={c.suelo} />
      <Linea desde={[0.14, 0, 0.05]} hasta={[0.08, 0.6, 0]} grosor={0.012} color={c.suelo} />
      <group position={[0, 0.78, 0.01]}>
        <Pieza forma="caja" medidas={[0.42, 0.46, 0.02]} color={c.marfil} />
        <Pieza forma="caja" medidas={[0.1, b(0.3), 0.02]} color={c.oro} brillo={resaltado ? c.oro : undefined} posicion={[-0.08, -0.17 + b(0.3) / 2, 0.015]} />
        <Pieza forma="caja" medidas={[0.1, b(0.23), 0.02]} color={c.sec} posicion={[0.08, -0.17 + b(0.23) / 2, 0.015]} />
        <Cartel texto="41" posicion={[-0.08, -0.15 + b(0.3) + 0.04, 0.03]} alto={0.06} fondo="transparent" colorTexto={c.prota} rotacion={[0, 0, 0.0001]} />
        <Cartel texto="32" posicion={[0.08, -0.15 + b(0.23) + 0.04, 0.03]} alto={0.06} fondo="transparent" colorTexto={c.sec} rotacion={[0, 0, 0.0001]} />
        <Cartel texto="estrellaron" posicion={[-0.08, -0.2, 0.03]} alto={0.03} fondo="transparent" colorTexto={c.carbon} rotacion={[0, 0, 0.0001]} />
        <Cartel texto="tocaron" posicion={[0.08, -0.2, 0.03]} alto={0.03} fondo="transparent" colorTexto={c.carbon} rotacion={[0, 0, 0.0001]} />
      </group>
      <Sombra posicion={[0, 0, 0]} radio={0.18} />
    </group>
  );
};

export const Sello: React.FC<ParteProps> = ({paleta, resaltado}) => {
  const c = col(paleta);
  return (
    <Cartel texto="IGUAL" posicion={[0.42, PANT_Y + 0.2, PANT_Z + 0.04]} alto={0.15} fondo={resaltado ? c.oro : c.prota} colorTexto={c.marfil} rotacion={[0, 0, -0.18]} />
  );
};

/** Calendario sobre la pantalla: hojas pasadas 0..7. */
export const Calendario: React.FC<ParteProps & {hojas?: number}> = ({paleta, resaltado, hojas = 7}) => {
  const c = col(paleta);
  return (
    <group position={[0, 1.66, -0.82]}>
      <Pieza forma="caja" medidas={[0.3, 0.26, 0.03]} color={c.marfil} />
      <Pieza forma="caja" medidas={[0.3, 0.07, 0.035]} color={resaltado ? c.oro : c.prota} posicion={[0, 0.1, 0.004]} />
      {[-0.08, 0.08].map((x) => (
        <Pieza key={x} forma="toro" medidas={[0.018, 0.005]} color={c.oro} posicion={[x, 0.135, 0.02]} />
      ))}
      <Cartel texto={`+${Math.round(hojas)}`} posicion={[0, -0.03, 0.02]} alto={0.12} fondo="transparent" colorTexto={c.carbon} rotacion={[0, 0, 0.0001]} />
      <Cartel texto="días" posicion={[0, -0.1, 0.02]} alto={0.04} fondo="transparent" colorTexto={c.carbon} rotacion={[0, 0, 0.0001]} />
    </group>
  );
};

/** Tarjeta con un vidrio roto dibujado (en la mano de la investigadora ya acercada). */
export const POS_VIDRIOS: V3 = [-0.48, 0.92, -0.1];
export const Vidrios: React.FC<ParteProps> = ({paleta, resaltado}) => {
  const c = col(paleta);
  const grieta: [number, number][] = [[0.1, 0.06], [-0.09, 0.07], [-0.11, -0.05], [0.07, -0.08], [0.0, 0.1], [0.12, -0.01]];
  return (
    <group position={POS_VIDRIOS} rotation={[0, 0, 0.06]}>
      <Pieza forma="caja" medidas={[0.3, 0.24, 0.012]} color={resaltado ? c.oro : c.marfil} />
      <Pieza forma="caja" medidas={[0.22, 0.16, 0.006]} color="#9CC3C8" posicion={[0, 0, 0.008]} opacidad={0.8} />
      {grieta.map(([x, y], i) => (
        <Linea key={i} desde={[0.01, 0.0, 0.014]} hasta={[x * 0.9, y * 0.9, 0.014]} grosor={0.004} color={c.sec} />
      ))}
    </group>
  );
};

export const Tachado: React.FC<ParteProps> = ({paleta, resaltado}) => {
  const c = col(paleta);
  const k = resaltado ? c.oro : c.prota;
  const [x, y, z] = POS_VIDRIOS;
  return (
    <group position={[x, y, z + 0.03]}>
      <Linea desde={[-0.15, -0.12, 0]} hasta={[0.15, 0.12, 0]} grosor={0.016} color={k} />
      <Linea desde={[-0.15, 0.12, 0]} hasta={[0.15, -0.12, 0]} grosor={0.016} color={k} />
    </group>
  );
};

/** Barras de «sí vi vidrios» (32 %, 14 %, 12 %), sobre la pantalla. */
export const BarrasVidrios: React.FC<ParteProps & {altura?: number}> = ({paleta, resaltado, altura = 1}) => {
  const c = col(paleta);
  const datos: [string, number, string][] = [['estrellaron', 32, c.oro], ['chocaron', 14, c.sec], ['sin verbo', 12, c.sec]];
  return (
    <group position={[0, 1.66, -0.8]}>
      <Pieza forma="caja" medidas={[0.72, 0.3, 0.025]} color={c.marfil} />
      {datos.map(([t, v, k], i) => {
        const h = Math.max(0.001, (v / 32) * 0.17 * altura);
        const x = -0.22 + i * 0.22;
        return (
          <group key={t} position={[x, -0.1, 0.015]}>
            <Pieza forma="caja" medidas={[0.1, h, 0.02]} color={resaltado && i === 0 ? c.prota : k} posicion={[0, h / 2, 0]} />
            <Cartel texto={`${v}%`} posicion={[0, h + 0.03, 0.02]} alto={0.045} fondo="transparent" colorTexto={i === 0 ? c.prota : c.sec} rotacion={[0, 0, 0.0001]} />
            <Cartel texto={t} posicion={[0, -0.025, 0.02]} alto={0.028} fondo="transparent" colorTexto={c.carbon} rotacion={[0, 0, 0.0001]} />
          </group>
        );
      })}
    </group>
  );
};

// Rompecabezas del recuerdo dentro de la cabeza: 3 x 2 piezas, falta la de arriba a la derecha.
const T = 0.068;
const CENTRO_PUZ: V3 = [POS_CABEZA[0] + 0.01, POS_CABEZA[1] + 0.07, POS_CABEZA[2] + 0.04];
const celda = (i: number, j: number): V3 => [CENTRO_PUZ[0] + (i - 1) * T, CENTRO_PUZ[1] + (0.5 - j) * T, CENTRO_PUZ[2]];
export const POS_PIEZA: V3 = celda(2, 0);

export const Rompecabezas: React.FC<ParteProps> = ({paleta, resaltado}) => {
  const c = col(paleta);
  const items: React.ReactNode[] = [];
  for (let j = 0; j < 2; j++)
    for (let i = 0; i < 3; i++) {
      if (i === 2 && j === 0) continue;
      items.push(
        <Pieza key={`${i}${j}`} forma="caja" medidas={[T * 0.94, T * 0.94, 0.012]} color={resaltado ? c.oro : (i + j) % 2 ? c.marfil : c.extra}
          posicion={celda(i, j)} opacidad={0.85} />,
      );
    }
  return <group>{items}</group>;
};

/** La pieza-palabra dorada, ya encajada en el hueco del rompecabezas. */
export const PiezaPalabra: React.FC<ParteProps> = ({paleta}) => {
  const c = col(paleta);
  return (
    <group position={POS_PIEZA}>
      <Pieza forma="caja" medidas={[T * 0.94, T * 0.94, 0.016]} color={c.oro} brillo={c.oro} />
      <Cartel texto="estrellaron" posicion={[0, 0, 0.012]} alto={0.014} fondo="transparent" colorTexto={c.prota} rotacion={[0, 0, 0.0001]} />
    </group>
  );
};

// ---------- el mundo según el paso ----------
export const Mundo: React.FC<MundoProps> = ({paso, frame, fps, paleta, ocultar = [], resaltar = []}) => {
  const ve = (n: string) => !ocultar.includes(n);
  const r = (n: string) => resaltar.includes(n);
  const en = (...pasos: number[]) => pasos.includes(paso);
  const sep = division(paso);
  const base = {paleta, frame};
  return (
    <group>
      {ve('sala') ? <Sala {...base} resaltado={r('sala')} luz={penumbra(paso)} /> : null}
      {ve('pantalla') ? <Pantalla {...base} resaltado={r('pantalla')} /> : null}
      {ve('autos') && paso >= 2 ? <Autos {...base} resaltado={r('autos')} avance={avanceAutos(paso)} /> : null}
      {ve('butacas') ? <Butacas {...base} resaltado={r('butacas')} sep={sep} /> : null}
      {ve('estudiantes') && paso >= 4 ? <Estudiantes {...base} fps={fps} resaltado={r('estudiantes')} sep={sep} /> : null}
      {ve('mia') ? <Mia {...base} fps={fps} resaltado={r('mia')} pose={paso === 10 ? 'sorprendida' : 'parado'} /> : null}
      {ve('cabeza') && en(0, 10, 11) ? <Cabeza {...base} fps={fps} resaltado={r('cabeza')} /> : null}
      {ve('cajon') && paso === 0 ? <CajonRecuerdo {...base} resaltado={r('cajon')} /> : null}
      {ve('rompecabezas') && en(10, 11) ? <Rompecabezas {...base} resaltado={r('rompecabezas')} /> : null}
      {ve('pieza') && paso === 11 ? <PiezaPalabra {...base} resaltado={r('pieza')} /> : null}
      {ve('palabra') && en(1, 7, 8, 9, 10) ? <Palabra {...base} fps={fps} resaltado={r('palabra')} /> : null}
      {ve('investigadores') && paso >= 3 ? <Investigadores {...base} fps={fps} paso={paso} resaltado={r('investigadores')} /> : null}
      {ve('rotulo') && paso >= 3 && paso <= 7 ? <Rotulo {...base} resaltado={r('rotulo')} /> : null}
      {ve('tarjeta') && paso === 4 ? <Tarjeta {...base} resaltado={r('tarjeta')} /> : null}
      {ve('burbujas') && en(5, 6) ? <Burbujas {...base} fps={fps} resaltado={r('burbujas')} /> : null}
      {ve('barras') && paso === 6 ? <Barras {...base} resaltado={r('barras')} altura={crecerBarras(paso, 6)} /> : null}
      {ve('sello') && paso === 7 ? <Sello {...base} resaltado={r('sello')} /> : null}
      {ve('calendario') && en(8, 9) ? <Calendario {...base} resaltado={r('calendario')} hojas={7} /> : null}
      {ve('vidrios') && en(8, 9) ? <Vidrios {...base} resaltado={r('vidrios')} /> : null}
      {ve('tachado') && paso === 9 ? <Tachado {...base} resaltado={r('tachado')} /> : null}
      {ve('barrasvidrios') && paso >= 10 ? <BarrasVidrios {...base} resaltado={r('barrasvidrios')} altura={crecerBarras(paso, 10)} /> : null}
    </group>
  );
};

