// Escena 2 · «Imagina que ves un choque de autos en un video.»
// Paso 1 → 2: la pantalla se enciende, la palabra flotante se apaga, entran los dos autitos,
// aceleran y chocan en el centro; Mía se sobresalta y vuelve a quedarse quieta mirando.
import React from 'react';
import {Easing, interpolate} from 'remotion';
import {EscenaProps, Pieza, Linea, Flecha, Etiqueta, aparecer, momento} from '../lib3d';
import {Efecto} from '../lib25d';
import {Mundo, Autos, Mia, Palabra} from './Mundo';

const PY = 1.06;
const PZ = -0.86;
const CALLE_Y = PY - 0.16;

export const Escena1: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [rojo, azul, oro] = paleta.acentos;
  const marfil = paleta.tinta;

  const tImagina = momento(palabras, fps, 'Imagina', 1);
  const tVes = momento(palabras, fps, 'ves', 21);
  const tChoque = momento(palabras, fps, 'choque', 32);
  const tAutos = momento(palabras, fps, 'autos', 45);
  const tVideo = momento(palabras, fps, 'video', 64);

  // 1) «Imagina»: el proyector enciende la pantalla y la palabra flotante se apaga.
  const destelloPant = interpolate(frame, [tImagina, tImagina + 3, tImagina + 12], [0, 0.45, 0], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });
  const palabraSale = 1 - aparecer(frame, tImagina + 2, 10);

  // 2) «ves»: los autitos aparecen en los bordes de la pantalla.
  const entran = aparecer(frame, tVes - 4, 6);

  // 3) «choque»: aceleran hacia el centro y chocan.
  const avance = interpolate(frame, [tVes + 1, tChoque], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
    easing: Easing.in(Easing.quad),
  });
  const fc = frame - tChoque;
  const sacudida = fc > 0 ? Math.exp(-fc / 4) * Math.sin(fc * 1.9) * 0.012 : 0;
  const chispa = fc >= 0 && fc < 18;
  const anda = avance > 0.02 && avance < 1 ? 1 : 0;
  const xAuto = 0.52 - 0.39 * avance;

  // Mía se sobresalta con el choque y vuelve a quedarse quieta.
  const susto = frame >= tChoque && frame < tChoque + 30;

  // 4) «autos»: los autitos se resaltan durante 1 s.
  const resaltaAutos = frame >= tAutos && frame < tAutos + 30;

  // 5) «video»: la etiqueta señala la pantalla.
  const etiqueta = aparecer(frame, tVideo - 2, 8);

  return (
    <group>
      <Mundo paso={1} frame={frame} fps={fps} paleta={paleta} ocultar={['palabra', 'mia']} />

      {/* el proyector ilumina la pantalla un instante */}
      {destelloPant > 0.01 ? (
        <Pieza forma="caja" medidas={[1.4, 0.78, 0.004]} color={marfil} brillo={marfil} intensidadBrillo={1}
          posicion={[0, PY, PZ + 0.014]} opacidad={destelloPant} contorno={false} />
      ) : null}

      {/* la palabra flotante se encoge y desaparece (en el paso 2 ya no está) */}
      {palabraSale > 0.01 ? (
        <group position={[0, 0.86 + (1 - palabraSale) * 0.12, 0.3]} scale={palabraSale}>
          <group position={[0, -0.86, -0.3]}>
            <Palabra paleta={paleta} frame={frame} fps={fps} />
          </group>
        </group>
      ) : null}

      {/* los autitos en la pantalla: aparecen, aceleran y chocan */}
      {entran > 0.01 ? (
        <group position={[sacudida, CALLE_Y - 0.04, PZ]} scale={[1, entran, 1]}>
          <group position={[0, -(CALLE_Y - 0.04), -PZ]}>
            <Autos paleta={paleta} avance={avance} resaltado={resaltaAutos} />
          </group>
        </group>
      ) : null}

      {/* estelas de velocidad detrás de cada auto */}
      {anda ? (
        <>
          <Linea desde={[-0.62, CALLE_Y + 0.02, PZ + 0.04]} hasta={[-xAuto - 0.14, CALLE_Y + 0.02, PZ + 0.04]}
            grosor={0.006} color={marfil} discontinua />
          <Linea desde={[0.62, CALLE_Y + 0.02, PZ + 0.04]} hasta={[xAuto + 0.14, CALLE_Y + 0.02, PZ + 0.04]}
            grosor={0.006} color={marfil} discontinua />
          <Flecha desde={[-0.5, CALLE_Y + 0.17, PZ + 0.05]} hasta={[-0.2, CALLE_Y + 0.17, PZ + 0.05]} color={rojo}
            grosor={0.014} progreso={aparecer(frame, tVes, 6)} />
          <Flecha desde={[0.5, CALLE_Y + 0.17, PZ + 0.05]} hasta={[0.2, CALLE_Y + 0.17, PZ + 0.05]} color={azul}
            grosor={0.014} progreso={aparecer(frame, tVes, 6)} />
        </>
      ) : null}

      {/* el golpe: chispas y destello dorado en el punto del choque */}
      {chispa ? (
        <>
          <Efecto tipo="destello" tam={0.42} color={oro} posicion={[0, CALLE_Y + 0.02, PZ + 0.06]} frame={frame} fps={fps} />
          <Efecto tipo="chispa" tam={0.34} color={oro} posicion={[0, CALLE_Y + 0.05, PZ + 0.07]} frame={frame} fps={fps} />
        </>
      ) : null}

      {/* Mía mira la pantalla y se sobresalta con el choque */}
      <Mia paleta={paleta} frame={frame} fps={fps} pose={susto ? 'sorprendida' : 'parado'} />
      {susto && fc < 16 ? (
        <Efecto tipo="ondas" tam={0.22} color={marfil} posicion={[0.12, 0.58, 0.18]} frame={frame} fps={fps} />
      ) : null}

      {/* rótulo: el video */}
      <Etiqueta texto="el video" punto={[0.6, PY + 0.28, PZ + 0.03]} desplazamiento={[0.28, 0.3, 0.35]}
        escala={etiqueta} color={marfil} alto={0.13} />
    </group>
  );
};

escenas.Escena2:
// Escena 3 · «En 1974, Elizabeth Loftus y John Palmer hicieron justo eso.»
// Encuadre picado_izq. Paso 2 → paso 3: cae el rótulo «1974» sobre la pantalla y aparecen,
// uno por uno, los dos investigadores (carpeta y cronómetro) a la izquierda de la pantalla.
import React from 'react';
import {spring, interpolate} from 'remotion';
import {EscenaProps, Pieza, Linea, Brillo, Etiqueta, aparecer, momento, caer} from '../lib3d';
import {Persona2D, Sombra, Efecto} from '../lib25d';
import {Mundo, Rotulo, posInvestigadora} from './Mundo';

const ventana = (frame: number, t0: number, t1: number, d = 6) =>
  Math.max(0, Math.min(aparecer(frame, t0, d), 1 - aparecer(frame, t1, d)));

export const Escena2: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [prota, sec, oro] = paleta.acentos;
  const marfil = paleta.tinta;

  // golpes con la voz
  const tEn = momento(palabras, fps, 'En', 1);
  const tSetenta = momento(palabras, fps, 'setenta', 27);
  const tCuatro = momento(palabras, fps, 'cuatro', 40);
  const tEliza = momento(palabras, fps, 'Elizabeth', 60);
  const tJohn = momento(palabras, fps, 'John', 94);
  const tHicieron = momento(palabras, fps, 'hicieron', 114);
  const tJusto = momento(palabras, fps, 'justo', 127);
  const fin = duracion;

  // 1) «En…»: la pantalla del video de choque se enciende en dorado (lo que «hicieron»)
  const pantallaResalta = frame >= tEn && frame < tEn + 20;

  // 2) «setenta»: el rótulo del año cae y se asienta sobre la pantalla
  const c = caer(frame, fps, tSetenta, 1.2);
  const destello = ventana(frame, tSetenta, tSetenta + 34, 4);
  const pulsoAnio = frame >= tCuatro ? Math.exp(-(frame - tCuatro) / 8) : 0;

  // 3) «Elizabeth»: la investigadora de la carpeta aparece con rebote
  const sA = spring({frame: frame - tEliza, fps, config: {damping: 11, stiffness: 140}});
  const resA = frame >= tEliza && frame < tEliza + 36;
  const etiA = ventana(frame, tEliza + 2, tEliza + 32);

  // 4) «John Palmer»: el investigador del cronómetro
  const sB = spring({frame: frame - tJohn, fps, config: {damping: 11, stiffness: 140}});
  const resB = frame >= tJohn && frame < tJohn + 36;
  const etiB = ventana(frame, tJohn + 2, tJohn + 30);

  // 5) «hicieron justo eso»: línea punteada de la carpeta a los autos chocados, y los autos se resaltan
  const traza = aparecer(frame, tHicieron, 14);
  const trazaFuera = interpolate(frame, [fin - 12, fin - 3], [1, 0], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});
  const autosResalta = frame >= tJusto && frame < Math.min(tJusto + 20, fin - 3);
  const tic = frame >= tHicieron ? Math.exp(-(frame - tHicieron) / 10) : 0;

  const a = posInvestigadora(3);
  const posB: [number, number, number] = [-1.02, 0.14, -0.4];
  const resaltar = [...(pantallaResalta ? ['pantalla'] : []), ...(autosResalta ? ['autos'] : [])];

  return (
    <group>
      <Mundo paso={2} frame={frame} fps={fps} paleta={paleta} resaltar={resaltar} />

      {/* rótulo «1974» que cae sobre la pantalla */}
      {c.escala > 0.001 ? (
        <group position={[0, c.y, 0]}>
          <Rotulo paleta={paleta} />
        </group>
      ) : null}
      {destello > 0 ? (
        <group>
          <Efecto tipo="destello" tam={0.75 * destello} color={oro} posicion={[0, 1.66, -0.88]} frame={frame} fps={fps} opacidad={0.7 * destello} />
          <Brillo posicion={[0, 1.66, -0.8]} color={oro} radio={0.012 + 0.03 * pulsoAnio} luz={1.2 * destello} />
        </group>
      ) : null}

      {/* investigadora con carpeta (Elizabeth Loftus) */}
      {sA > 0.001 ? (
        <group position={[a[0], 0.14, a[2]]} scale={[sA, sA, sA]}>
          <Persona2D pose="parado" color={resA ? oro : marfil} alto={0.8} posicion={[0, 0, 0]} frame={frame} fps={fps} />
          <Pieza forma="caja" medidas={[0.09, 0.12, 0.015]} color={sec} posicion={[-0.12, 0.46, 0.04]} rotacion={[0, 0, 0.2]}
            brillo={traza > 0 && trazaFuera > 0 ? oro : undefined} />
        </group>
      ) : null}
      {sA > 0.001 ? <Sombra posicion={[a[0], 0.14, a[2]]} radio={0.2 * Math.min(1, sA)} /> : null}

      {/* investigador con cronómetro (John Palmer) */}
      {sB > 0.001 ? (
        <group position={posB} scale={[sB, sB, sB]}>
          <Persona2D pose="parado" color={resB ? oro : marfil} alto={0.84} posicion={[0, 0, 0]} frame={frame} fps={fps} />
          <group position={[0.12, 0.48, 0.04]} rotation={[0, 0, Math.sin(frame * 0.9) * 0.15 * tic]}>
            <Pieza forma="cilindro" medidas={[0.035, 0.035, 0.015, 20]} color={oro} rotacion={[Math.PI / 2, 0, 0]} brillo={tic > 0.05 ? oro : undefined} />
            <Pieza forma="caja" medidas={[0.012, 0.02, 0.012]} color={oro} posicion={[0, 0.045, 0]} />
          </group>
        </group>
      ) : null}
      {sB > 0.001 ? <Sombra posicion={posB} radio={0.2 * Math.min(1, sB)} /> : null}

      {/* nombres cortos, a un lado y por encima de cada uno */}
      <Etiqueta texto="loftus" punto={[a[0], 0.98, a[2] + 0.02]} desplazamiento={[0.12, 0.36, 0.3]} escala={etiA} alto={0.13} color={marfil} />
      <Etiqueta texto="palmer" punto={[posB[0], 1.02, posB[2] + 0.02]} desplazamiento={[0.16, 0.42, 0.36]} escala={etiB} alto={0.13} color={marfil} />

      {/* «hicieron justo eso»: de la carpeta al video del choque */}
      {traza > 0 && trazaFuera > 0 ? (
        <group>
          <Linea desde={[-0.95, 0.66, -0.48]} hasta={[-0.2, 0.92, -0.8]} grosor={0.009} color={oro} progreso={traza * trazaFuera} brillo discontinua />
          <Brillo posicion={[-0.95 + 0.75 * traza, 0.66 + 0.26 * traza, -0.48 - 0.32 * traza]} color={oro} radio={0.022 * trazaFuera} />
        </group>
      ) : null}

      {/* motas de polvo dorado en el haz del proyector (capa delantera, sutil) */}
      {[0, 1, 2, 3].map((i) => {
        const t = ((frame + i * 37) % 150) / 150;
        return (
          <Brillo key={i} posicion={[0.35 - i * 0.22, 1.25 + 0.3 * Math.sin(t * 6.28 + i), 0.9 - t * 0.6]} color={i % 2 ? oro : prota} radio={0.007} />
        );
      })}
    </group>
  );
};
